import java.nio.file.*;import java.security.*;public class ReadTlsStore28 {public static void main(String[] args)throws Exception{var file=Path.of(args[0]);var bytes=Files.readAllBytes(file);System.out.println("STORE_BYTES="+bytes.length+" STORE_SHA256="+java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes)));var store=KeyStore.getInstance("PKCS12");char[] pass=System.getenv("STORE_PASSWORD").toCharArray();try(var in=Files.newInputStream(file)){store.load(in,pass);}var aliases=store.aliases();while(aliases.hasMoreElements()){String alias=aliases.nextElement();System.out.println("ALIAS="+alias+" PRIVATE_KEY="+store.isKeyEntry(alias)+" CERT_SHA256="+java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(store.getCertificate(alias).getEncoded())));if(store.isKeyEntry(alias)){var key=store.getKey(alias,pass);if(key==null)throw new IllegalStateException("PRIVATE_KEY_REQUIRED");}}java.util.Arrays.fill(pass,'\0');System.out.println("REAL_CONTAINER_PKCS12_LOAD_PASSED");}}